import * as fs from "node:fs";
import * as path from "node:path";
export default function (pi: any) {
  pi.registerTool({
    name: "fsx",
    label: "Fsx",
    description: "Harness helper: change the workspace outside the extension under test.",
    parameters: {
      type: "object",
      properties: {
        op: { type: "string" },
        path: { type: "string" },
        content: { type: "string" },
        target: { type: "string" },
        mtime: { type: "number" },
      },
      required: ["op", "path"],
    },
    async execute(_id: string, params: any, _signal: any, _update: any, ctx: any) {
      const p = path.resolve(ctx.cwd, params.path);
      if (params.op === "write") {
        fs.mkdirSync(path.dirname(p), { recursive: true });
        fs.writeFileSync(p, params.content ?? "");
      } else if (params.op === "unlink") {
        fs.unlinkSync(p);
      } else if (params.op === "utimes") {
        fs.utimesSync(p, params.mtime, params.mtime);
      } else if (params.op === "symlink") {
        fs.mkdirSync(path.dirname(p), { recursive: true });
        fs.symlinkSync(path.resolve(ctx.cwd, params.target), p, "dir");
      } else if (params.op === "find") {
        // every regular file named params.content under params.path, with its mtime
        const found: string[] = [];
        const walk = (dir: string) => {
          for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
            const full = path.join(dir, entry.name);
            if (entry.isDirectory()) walk(full);
            else if (entry.name === params.content) found.push(path.relative(p, full) + " " + fs.statSync(full).mtimeMs);
          }
        };
        walk(p);
        found.sort();
        return { content: [{ type: "text", text: found.join("\n") || "none" }], details: {} };
      } else if (params.op === "mkdir") {
        fs.mkdirSync(p, { recursive: true });
      } else {
        throw new Error("fsx: unknown op " + params.op);
      }
      return { content: [{ type: "text", text: "fsx " + params.op + " ok" }], details: {} };
    },
  });
}

import * as fs from "node:fs";
import * as path from "node:path";
export default function (pi: any) {
  pi.registerTool({
    name: "forkfile",
    label: "Forkfile",
    description: "Harness helper: write the forked copy of the current session file, with its leaf on the entry after which the assistant said `upto`.",
    parameters: {
      type: "object",
      properties: { name: { type: "string" }, id: { type: "string" }, upto: { type: "string" } },
      required: ["name", "id"],
    },
    async execute(_id: string, params: any, _signal: any, _update: any, ctx: any) {
      const source = ctx.sessionManager.getSessionFile();
      const lines = fs.readFileSync(source, "utf8").split("\n").filter((line: string) => line !== "");
      const entries = lines.map((line: string) => JSON.parse(line)).filter((entry: any) => entry.type !== "session");
      const byId = new Map(entries.map((entry: any) => [entry.id, entry]));
      const leafEntry = params.upto === undefined ? undefined : entries.find((e: any) => e.type === "message" && e.message?.role === "assistant" && Array.isArray(e.message.content) && e.message.content.some((c: any) => c.type === "text" && c.text === params.upto));
      const onPath = new Set<string>();
      for (let id: string | null | undefined = leafEntry?.id; id; id = (byId.get(id) as any)?.parentId) onPath.add(id);
      // entries after the selected leaf first, the path to it last: the file's last entry is the leaf
      const ordered = leafEntry ? [...entries.filter((e: any) => !onPath.has(e.id)), ...entries.filter((e: any) => onPath.has(e.id))] : entries;
      const header = { type: "session", version: 3, id: params.id, timestamp: "2026-11-06T10:00:00.000Z", cwd: ctx.cwd, parentSession: source };
      fs.writeFileSync(path.join(path.dirname(source), params.name), [header, ...ordered].map((entry) => JSON.stringify(entry)).join("\n") + "\n");
      return { content: [{ type: "text", text: "forkfile " + params.name + " ok" }], details: {} };
    },
  });
}
